const money=cents=>(cents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const productId=Number(new URLSearchParams(location.search).get('id'));
const container=document.querySelector('#product-page-content');
function escapeHtml(value){const box=document.createElement('div');box.textContent=value||'';return box.innerHTML}
function renderProduct(){const p=produtos[productId];if(!p){container.innerHTML='<section class="missing-product"><h1>Produto não encontrado</h1><p>Volte ao catálogo e escolha um produto.</p><a class="primary-link" href="index.html">Ver catálogo</a></section>';return}document.title=p.nome+' · Almeida Construções';const first=p.variacoes[0];const description=p.descricao||`Produto ${p.marca} da categoria ${p.grupo}. Selecione a variação desejada para consultar o valor da Almeida Construções.`;const detail=productDetail(p);const image=p.imagem?`<img class="product-image processing" data-clean-image src="${escapeHtml(p.imagem)}" alt="${escapeHtml(p.nome)}">`:`<div class="product-image product-placeholder" aria-hidden="true">${escapeHtml(p.marca[0])}</div>`;container.innerHTML=`<article class="product-detail-page"><section class="product-visual">${image}</section><section class="product-content"><small>${escapeHtml(p.marca.toUpperCase())} · ${escapeHtml(p.grupo.toUpperCase())}</small><h1>${escapeHtml(p.nome)}</h1><p class="product-description">${escapeHtml(description)}</p><div class="product-information"><section><h2>Benefícios e funcionalidades</h2><ul>${detail.b.map(item=>`<li>${escapeHtml(item)}</li>`).join('')}</ul></section><section><h2>Onde aplicar</h2><p>${escapeHtml(detail.a)}</p></section><section><h2>Como usar</h2><p>${escapeHtml(detail.u)}</p></section></div><label class="field">Escolha a variação<select id="product-variant">${p.variacoes.map((v,index)=>`<option value="${index}">${escapeHtml(v.nome)} · ${money(v.preco)}</option>`).join('')}</select></label><div id="product-price" class="product-price"></div><button id="product-add" class="primary">Adicionar ao carrinho</button><p class="product-policy">PIX ou dinheiro: 10% de desconto. Cartão: até 4x sem juros. Disponibilidade confirmada pela loja.</p>${p.fonte?`<a class="source-link" href="${escapeHtml(p.fonte)}" target="_blank" rel="noopener">Informações do fabricante ↗</a>`:''}</section></article>`;const update=()=>{const variant=p.variacoes[Number(document.querySelector('#product-variant').value)];document.querySelector('#product-price').innerHTML=`<strong>${money(variant.preco)}</strong><span>${money(Math.round(variant.preco*.9))} no PIX ou dinheiro</span><small>ou até 4x de ${money(Math.round(variant.preco/4))} sem juros</small>`};AlmeidaImageCleanup.watch(container);document.querySelector('#product-variant').onchange=update;update();document.querySelector('#product-add').onclick=()=>{const selected=Number(document.querySelector('#product-variant').value);const cart=JSON.parse(sessionStorage.getItem('almeida-cart')||'[]');const item=cart.find(i=>i.id===productId&&i.vi===selected);if(item)item.qty++;else cart.push({id:productId,vi:selected,qty:1});sessionStorage.setItem('almeida-cart',JSON.stringify(cart));location.href='index.html?cart=1'}}
async function loadProductFromSupabase(){try{const response=await fetch(ALMEIDA_SUPABASE_URL+'/rest/v1/products?active=eq.true&select=brand,name,subcategory,description,image_url,image_override_url,source_url,product_variants(name,price_cents,active)&order=name.asc',{headers:{apikey:ALMEIDA_SUPABASE_KEY,Authorization:'Bearer '+ALMEIDA_SUPABASE_KEY}});if(!response.ok)throw new Error('Catalog status '+response.status);const remote=await response.json();const normalized=remote.map((p,id)=>({id,marca:p.brand,nome:p.name,grupo:p.subcategory,descricao:p.description,imagem:p.image_override_url||localProductImage(p.brand,p.name,p.image_url),fonte:p.source_url,variacoes:(p.product_variants||[]).filter(v=>v.active).map(v=>({nome:v.name,preco:v.price_cents}))})).filter(p=>p.variacoes.length);if(normalized.length){produtos=normalized;renderProduct()}}catch(error){console.info('Detalhes locais usados enquanto o banco não está disponível.',error)}}
renderProduct();loadProductFromSupabase();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js');
